// main.js
let worker = new Worker("worker.js");

worker.postMessage({ numbers: [1, 2, 3, 4, 5] });

worker.onmessage = (e) => {
  console.log("Result:", e.data.sum);  // 15
};

// worker.js
self.onmessage = (e) => {
  let sum = e.data.numbers.reduce((a, b) => a + b, 0);
  self.postMessage({ sum });
};

// main.js — sending structured data
let worker = new Worker("worker.js");
let data = {
  users: [{ name: "Alex" }, { name: "Sam" }],
  config: new Map([["theme", "dark"]])
};

// Deep clone automatically
worker.postMessage(data);

// Transferable: zero-copy transfer of ArrayBuffer
let buffer = new ArrayBuffer(1024 * 1024);  // 1MB
worker.postMessage(buffer, [buffer]);  // buffer is now unusable in main!
console.log(buffer.byteLength);  // 0 — transferred!

// worker.js
self.onmessage = (e) => {
  console.log(e.data.users[0].name);  // "Alex"
  // e.data.config is a real Map!
};

// main.js
let sharedBuffer = new SharedArrayBuffer(4);
let view = new Int32Array(sharedBuffer);

let worker = new Worker("worker.js");
worker.postMessage(sharedBuffer);

// Atomically increment
Atomics.add(view, 0, 1);
console.log(Atomics.load(view, 0));  // value in shared memory

// worker.js
self.onmessage = (e) => {
  let view = new Int32Array(e.data);
  // Wait for main thread to write
  Atomics.wait(view, 0, 0);  // blocks until value !== 0
  console.log("Worker saw:", Atomics.load(view, 0));
};
